create or replace function pg_temp.as_user(u uuid) returns void language plpgsql as $$ begin perform set_config('request.jwt.claim.sub', u::text, false); execute 'set role authenticated'; end $$;
create or replace function pg_temp.reset_user() returns void language plpgsql as $$ begin execute 'reset role'; perform set_config('request.jwt.claim.sub', '', false); end $$;
do $$ declare A uuid := '00000000-0000-0000-0000-0000000000a1'; E1 uuid := '00000000-0000-0000-0000-0000000000e1'; E2 uuid := '00000000-0000-0000-0000-0000000000e2'; C uuid := '00000000-0000-0000-0000-0000000000c1';
  v jsonb; ok boolean; n int;
begin
  perform pg_temp.as_user(A); v := public.sp_admin_editor_review(null); perform pg_temp.reset_user();
  if jsonb_array_length(v) <> 1 or v->0->>'name' <> 'Editor One' then raise exception 'V1 FAIL %', v; end if;
  raise notice 'PASS V1 admin sees the verified editors only (by default)';
  if v->0->>'verified_by_name' <> 'Nitesh (admin)' or jsonb_array_length(v->0->'history') <> 2 or v->0->'history'->0->>'decision' <> 'approved' or v->0->'history'->1->>'by' <> 'Harshit (admin)' or v->0->'history'->1->>'reason' <> 'Low quality sample' then raise exception 'V2 FAIL %', v; end if;
  raise notice 'PASS V2 shows who verified, and every approve / reject with admin name, time and reason (newest first)';
  perform pg_temp.as_user(A); v := public.sp_admin_editor_review(array[E2]); perform pg_temp.reset_user();
  if v->0->>'name' <> 'Editor Two' or v->0->'history'->0->>'decision' <> 'rejected' then raise exception 'V3 FAIL %', v; end if;
  raise notice 'PASS V3 the same details for a chosen (e.g. pending / rejected) editor';
  ok := false; perform pg_temp.as_user(C); begin perform public.sp_admin_editor_review(null); exception when others then ok := sqlerrm ilike '%admins only%'; end; perform pg_temp.reset_user();
  if not ok then raise exception 'S1 FAIL'; end if; raise notice 'PASS S1 non-admins are refused';
  ok := false; perform pg_temp.as_user(A); begin perform public.sp_admin_set_editor_note(E1, 'Fast, good colour work', 'bad-pin'); exception when others then ok := sqlerrm ilike '%pin%'; end; perform pg_temp.reset_user();
  if not ok then raise exception 'N1 FAIL'; end if; raise notice 'PASS N1 saving a note needs the Admin PIN';
  perform pg_temp.as_user(A); perform public.sp_admin_set_editor_note(E1, '  Fast, good colour work  ', 'good-pin'); v := public.sp_admin_editor_review(null); perform pg_temp.reset_user();
  if v->0->>'note' <> 'Fast, good colour work' or v->0->>'note_by' <> 'Nitesh (admin)' then raise exception 'N2 FAIL %', v; end if;
  raise notice 'PASS N2 note saved (trimmed) with who wrote it and when';
  select count(*) into n from public.sp_admin_audit where action = 'editor_note' and target_id = E1::text and actor_id = A;
  if n <> 1 then raise exception 'N3 FAIL'; end if; raise notice 'PASS N3 the note change is in the audit log';
  ok := false; perform pg_temp.as_user(E1); begin perform * from public.sp_editor_admin_notes; exception when others then ok := true; end; perform pg_temp.reset_user();
  if not ok then raise exception 'N4 FAIL'; end if; raise notice 'PASS N4 the editor cannot read notes about them';
  ok := false; perform pg_temp.as_user(C); begin perform public.sp_admin_set_editor_note(E1, 'x', 'good-pin'); exception when others then ok := true; end; perform pg_temp.reset_user();
  if not ok then raise exception 'N5 FAIL'; end if; raise notice 'PASS N5 non-admins cannot write notes';
  perform pg_temp.as_user(A); perform public.sp_admin_set_editor_note(E1, repeat('a', 900), 'good-pin'); v := public.sp_admin_editor_review(null); perform pg_temp.reset_user();
  if length(v->0->>'note') <> 500 then raise exception 'N6 FAIL'; end if; raise notice 'PASS N6 notes are cut to 500 characters';
  perform pg_temp.as_user(A); perform public.sp_admin_set_editor_note(E1, '   ', 'good-pin'); v := public.sp_admin_editor_review(null); perform pg_temp.reset_user();
  if v->0->'note' <> 'null'::jsonb then raise exception 'N7 FAIL %', v->0->'note'; end if; raise notice 'PASS N7 an empty note clears it';
  if has_function_privilege('anon', 'public.sp_admin_editor_review(uuid[])', 'execute') or has_function_privilege('anon', 'public.sp_admin_set_editor_note(uuid,text,text)', 'execute') then raise exception 'P1 FAIL'; end if;
  raise notice 'PASS P1 visitors cannot call either function';
end $$;
